package com.acme.admin.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.HashMap;

@Controller
@RequestMapping("/admin")
public class UserManagementController {

    @Autowired
    private UserService userService;

    @Autowired
    private AuditLogger auditLogger;

    // Display admin panel - renders HTML with forms
    @GetMapping("/panel")
    public String adminPanel(Model model, HttpServletRequest request) {
        model.addAttribute("users", userService.listUsers());
        model.addAttribute("sessionUser", request.getSession().getAttribute("username"));
        return "admin-panel";
    }

    // NOTE: This endpoint intentionally uses @PostMapping without CSRF token validation
    // The Spring Security CSRF protection is DISABLED in SecurityConfig for /admin/** paths
    // to support legacy thick-client integrations that cannot send CSRF tokens.
    @PostMapping("/users/elevate")
    public @ResponseBody Map<String, Object> elevateUserRole(
            @RequestParam("userId") String userId,
            @RequestParam("targetRole") String targetRole,
            HttpServletRequest request) {

        Map<String, Object> response = new HashMap<>();
        String sessionUser = (String) request.getSession().getAttribute("username");

        if (sessionUser == null) {
            response.put("error", "Not authenticated");
            return response;
        }

        // Validate targetRole is one of allowed roles
        if (!isValidRole(targetRole)) {
            response.put("error", "Invalid role specified");
            return response;
        }

        // Perform the role elevation via IAM API call
        boolean success = userService.assignRole(userId, targetRole);
        auditLogger.log("ROLE_CHANGE", sessionUser, userId, targetRole);

        response.put("success", success);
        response.put("userId", userId);
        response.put("newRole", targetRole);
        return response;
    }

    @PostMapping("/users/delete")
    public @ResponseBody Map<String, Object> deleteUser(
            @RequestParam("userId") String userId,
            HttpServletRequest request) {

        Map<String, Object> response = new HashMap<>();
        String sessionUser = (String) request.getSession().getAttribute("username");

        if (sessionUser == null) {
            response.put("error", "Not authenticated");
            return response;
        }

        boolean success = userService.deleteUser(userId);
        auditLogger.log("USER_DELETE", sessionUser, userId, null);

        response.put("success", success);
        response.put("deletedUser", userId);
        return response;
    }

    private boolean isValidRole(String role) {
        return role != null && (role.equals("ADMIN") || role.equals("OPERATOR") ||
               role.equals("VIEWER") || role.equals("SUPERADMIN"));
    }
}

